package com.mantou.salesdialer.contacts;
import android.content.Context;import android.security.keystore.*;import android.util.AtomicFile;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;import org.json.*;
/** USB or paired LAN transport. Tokens encrypted by Android Keystore; passwords never persisted. */
final class EnterpriseSession {
 static final String ORIGIN="http://127.0.0.1:8790",ALIAS="sales-enterprise-session-v1";private static final Object LOCK=new Object();private static final ThreadLocal<Long> DEADLINE=new ThreadLocal<>();
 static void deadline(long at){DEADLINE.set(at);}static void clearDeadline(){DEADLINE.remove();}
 private static AtomicFile file(Context c){return new AtomicFile(new File(c.getFilesDir(),"enterprise-session.enc"));}
 private static SecretKey key()throws Exception{KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);if(!store.containsAlias(ALIAS)){KeyGenerator gen=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");gen.init(new KeyGenParameterSpec.Builder(ALIAS,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setKeySize(256).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());gen.generateKey();}return (SecretKey)store.getKey(ALIAS,null);}
 static JSONObject stored(Context c)throws Exception{synchronized(LOCK){if(!file(c).getBaseFile().exists())return null;byte[] bytes=file(c).readFully();if(bytes.length<29||bytes.length>16384)throw new IOException("AUTH_STATE_INVALID");Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Arrays.copyOfRange(bytes,0,12)));return new JSONObject(new String(cipher.doFinal(Arrays.copyOfRange(bytes,12,bytes.length)),StandardCharsets.UTF_8));}}
 private static void save(Context c,JSONObject value)throws Exception{synchronized(LOCK){Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());byte[] encrypted=cipher.doFinal(value.toString().getBytes(StandardCharsets.UTF_8));ByteArrayOutputStream bytes=new ByteArrayOutputStream();bytes.write(cipher.getIV());bytes.write(encrypted);AtomicFile f=file(c);FileOutputStream out=f.startWrite();try{out.write(bytes.toByteArray());f.finishWrite(out);}catch(Exception e){f.failWrite(out);throw e;}}}
 static void clear(Context c){synchronized(LOCK){file(c).delete();}}
 static String deviceId(Context c){var prefs=c.getSharedPreferences("enterprise-device",Context.MODE_PRIVATE);String id=prefs.getString("id","");if(id.isEmpty()){id=UUID.randomUUID().toString();if(!prefs.edit().putString("id",id).commit())throw new IllegalStateException("DEVICE_ID_WRITE_FAILED");}return id;}
 private static long remaining(){Long end=DEADLINE.get();return end==null?3500:Math.min(3500,end-android.os.SystemClock.elapsedRealtime());}
 private static JSONObject http(Context c,String path,JSONObject body,JSONObject session)throws Exception{
  if(!path.equals("/api/login")&&!path.equals("/api/command"))throw new IllegalArgumentException("INVALID_ENTERPRISE_PATH");long budget=remaining();if(budget<=0)throw new IOException("ENTERPRISE_TIMEOUT");long end=android.os.SystemClock.elapsedRealtime()+budget;String transport=EnterpriseConnection.tag(c);if(session!=null&&!session.optString("connection",ORIGIN).equals(transport))throw new IllegalStateException("CONNECTION_CHANGED_LOGIN_REQUIRED");HttpURLConnection conn=EnterpriseConnection.open(c,path,transport);conn.setInstanceFollowRedirects(false);conn.setConnectTimeout((int)Math.min(1500,budget));conn.setReadTimeout((int)Math.min(1500,budget));conn.setRequestMethod("POST");conn.setDoOutput(true);conn.setRequestProperty("Content-Type","application/json");
  if(session!=null)conn.setRequestProperty("Authorization","Bearer "+session.getString("token"));
  try{byte[] payload=body.toString().getBytes(StandardCharsets.UTF_8);if(payload.length>262144)throw new IOException("REQUEST_TOO_LARGE");conn.setFixedLengthStreamingMode(payload.length);try(OutputStream out=conn.getOutputStream()){out.write(payload);}int status=conn.getResponseCode();InputStream stream=status<400?conn.getInputStream():conn.getErrorStream();if(stream==null)throw new IOException("ENTERPRISE_UNAVAILABLE");ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream in=stream){byte[] buffer=new byte[4096];int read;while((read=in.read(buffer))!=-1){if(android.os.SystemClock.elapsedRealtime()>end)throw new IOException("ENTERPRISE_TIMEOUT");if(bytes.size()+read>2097152)throw new IOException("RESPONSE_TOO_LARGE");bytes.write(buffer,0,read);}}JSONObject result=new JSONObject(bytes.toString(StandardCharsets.UTF_8.name()));if(!result.optBoolean("ok")){String code=result.optString("error","ENTERPRISE_FAILED");if(!code.matches("[A-Z_]{1,80}"))code="ENTERPRISE_FAILED";throw new IllegalStateException(code);}if(status!=200)throw new IOException("ENTERPRISE_HTTP_FAILED");return result.getJSONObject("data");}finally{conn.disconnect();}
 }
 static JSONObject command(Context c,JSONObject body)throws Exception{return commandAs(c,stored(c),body);}
 static JSONObject commandAs(Context c,JSONObject session,JSONObject body)throws Exception{if(session==null)throw new IllegalStateException("AUTH_REQUIRED");return http(c,"/api/command",body,session);}
 static JSONObject statusAs(Context c,JSONObject session)throws Exception{return commandAs(c,session,new JSONObject().put("op","status"));}
 static JSONObject status(Context c)throws Exception{return command(c,new JSONObject().put("op","status"));}
 static JSONObject login(Context c,JSONObject body)throws Exception{EnterpriseQueue.disable(c);EnterpriseOperatorBatch.clear(c);try{pauseRemote(c);}catch(Exception ignored){}String transport=EnterpriseConnection.tag(c);JSONObject response=http(c,"/api/login",body,null);if(!transport.equals(EnterpriseConnection.tag(c)))throw new IllegalStateException("CONNECTION_CHANGED_LOGIN_REQUIRED");JSONObject session=new JSONObject().put("token",response.getString("token")).put("actor",response.getJSONObject("actor")).put("connection",transport);save(c,session);response.remove("token");response.put("loggedIn",true);return response;}
 static void pauseRemote(Context c)throws Exception{pauseRemoteAs(c,stored(c));}
 static void pauseRemoteAs(Context c,JSONObject session)throws Exception{if(session==null)return;JSONObject s=statusAs(c,session),q=s.optJSONObject("queue");if(q!=null&&!q.optString("state").equals("FINISHED")&&!q.optString("state").equals("STOPPED"))commandAs(c,session,new JSONObject().put("op","pause").put("queueId",q.getString("id")).put("expectedVersion",q.getLong("version")));}
}
